function test_CLOBRoundingDrainViaMicroFills() public {
    // Setup: Create order book with 100 orders of 1e6 each at price sqrtPriceX96 where rounding matters
    // Action: Fill each order with amountIn=1 in a loop (100 iterations)
    // Calculate: total output credited to makers vs single calculateFixedInput(100, price)
    uint160 price = 79228162514264337593543950336; // Q96 = 1:1
    uint256 singleCalc = FullMath.mulDivRoundingUp(
        FullMath.mulDivRoundingUp(100, price, Q96), price, Q96
    );
    uint256 sumOfIndividual = 0;
    for (uint256 i = 0; i < 100; i++) {
        sumOfIndividual += FullMath.mulDivRoundingUp(
            FullMath.mulDivRoundingUp(1, price, Q96), price, Q96
        );
    }
    // Assert: sum of individual rounds >= single calculation
    assertGe(sumOfIndividual, singleCalc, "Rounding accumulates");
    // The excess (sumOfIndividual - singleCalc) is extracted from executor refund
}

