function test_H03_tstorish_staleValue_afterActivation() public {
    // Setup: Deploy AMMStandardHook on chain without tstore support
    //        (uses sstore fallback)
    // Action 1: Execute a direct swap (beforeSwap stores amount=1e18 via sstore)
    //           Swap completes. afterSwap reads the value. But sstore slot NOT cleared.
    // Action 2: Call __activateTstore() -- copies sload(SLOT) -> tstore(SLOT)
    //           The stale 1e18 is now in transient storage
    // Action 3: Execute another direct swap with amount=1e6
    //           beforeSwap writes 1e6 to tstore (correct)
    //           afterSwap reads 1e6 from tload (correct -- overwritten)
    // KEY: The vulnerability window is if afterSwap runs WITHOUT beforeSwap
    //      (e.g., hook flags changed between activation and swap)
    //      Then afterSwap reads the stale 1e18 from the activation copy
    vm.store(address(hook), bytes32(uint256(0xFFFFFFFFFFFFFFFF)), bytes32(uint256(1e18)));
    hook.__activateTstore();
    uint256 staleValue = vm.load(address(hook), bytes32(uint256(0xFFFFFFFFFFFFFFFF)));
    assert(staleValue == 1e18); // stale value persists in tstore
}

